<script type="application/ld+json" dangerouslySetInnerHTML={{__html:"\r\n[\r\n  {\r\n    \"@context\": \"https://schema.org\",\r\n    \"@type\": \"HowTo\",\r\n    \"name\": \"How to Start a Career in Digital Marketing in India\",\r\n    \"description\": \"A step-by-step guide to launching a digital marketing career in India, from choosing the right course to landing your first job.\",\r\n    \"totalTime\": \"P4M\",\r\n    \"estimatedCost\": {\r\n      \"@type\": \"MonetaryAmount\",\r\n      \"currency\": \"INR\",\r\n      \"value\": \"25000\"\r\n    },\r\n    \"step\": [\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 1,\r\n        \"name\": \"Understand digital marketing fundamentals\",\r\n        \"text\": \"Learn what digital marketing covers ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â SEO, Google Ads, Meta Ads, Social Media, Email Marketing, Content Writing, and Analytics. Identify which specialisation matches your interest and career goal.\",\r\n        \"url\": \"https://dizitaladda.com/courses/digital-marketing-for-beginners\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 2,\r\n        \"name\": \"Choose the right course level\",\r\n        \"text\": \"Beginners with no marketing background should start with a 3-month beginner course. Working professionals switching careers should choose a 4-month professionals course. Those targeting agency or senior roles should consider a 6-12 month advanced or expert programme.\",\r\n        \"url\": \"https://dizitaladda.com/courses/digital-marketing-for-beginners\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 3,\r\n        \"name\": \"Earn Google and Meta certifications\",\r\n        \"text\": \"Complete Google Ads certification on Google Skillshop and Meta Blueprint certification during your course. These are free, globally recognised credentials that most employers look for in entry-level roles.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 4,\r\n        \"name\": \"Build a portfolio with live projects\",\r\n        \"text\": \"Run real campaigns on Google Ads and Meta Ads. Publish SEO-optimised blog posts. Build a WordPress website. Create GA4 reports. Recruiters look for evidence of hands-on work, not just certificates.\",\r\n        \"url\": \"https://dizitaladda.com/courses/advanced-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 5,\r\n        \"name\": \"Optimise your resume and LinkedIn profile\",\r\n        \"text\": \"Use keywords like SEO Executive, Performance Marketer, or PPC Specialist depending on your chosen track. Add campaign results with metrics ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â CTR, ROAS, organic traffic growth.\",\r\n        \"url\": \"https://dizitaladda.com/courses/digital-marketing-for-beginners\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 6,\r\n        \"name\": \"Apply for internships or entry-level roles\",\r\n        \"text\": \"Apply to digital marketing agencies, e-commerce companies, and startups. Entry-level roles include Social Media Executive, SEO Executive, PPC Executive, and Content Writer. Starting salary range: ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¹2.5-5 LPA in India.\",\r\n        \"url\": \"https://dizitaladda.com/courses/digital-marketing-for-beginners\"\r\n      }\r\n    ]\r\n  },\r\n  {\r\n    \"@context\": \"https://schema.org\",\r\n    \"@type\": \"HowTo\",\r\n    \"name\": \"How to Learn SEO and Rank on Google in 2026\",\r\n    \"description\": \"A practical step-by-step guide to learning Search Engine Optimisation and improving a website's Google ranking in 2026.\",\r\n    \"totalTime\": \"P3M\",\r\n    \"step\": [\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 1,\r\n        \"name\": \"Learn how search engines work\",\r\n        \"text\": \"Understand how Google crawls, indexes, and ranks pages. Study ranking factors: content quality, backlinks, page experience, and Core Web Vitals.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 2,\r\n        \"name\": \"Do keyword research\",\r\n        \"text\": \"Use Google Search Console, Google Keyword Planner, and Semrush to find keywords your target audience searches for. Focus on long-tail keywords with clear intent. In 2026, also optimise for conversational queries used in AI search engines.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 3,\r\n        \"name\": \"Optimise on-page elements\",\r\n        \"text\": \"Write keyword-rich title tags under 60 characters, meta descriptions under 160 characters, and H1 headings. Structure content with H2 and H3 subheadings. Include the target keyword naturally in the first 100 words, image alt text, and URL slug.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 4,\r\n        \"name\": \"Fix technical SEO issues\",\r\n        \"text\": \"Run a site audit using Screaming Frog or Semrush. Fix broken links, duplicate content, missing meta tags, slow page speed, and mobile usability issues. Improve Core Web Vitals: LCP, CLS, and INP.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 5,\r\n        \"name\": \"Build backlinks through content and outreach\",\r\n        \"text\": \"Create high-quality, shareable content. Reach out to relevant blogs for guest posts. List your business in authoritative directories. Quality backlinks from trusted domains increase domain authority.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 6,\r\n        \"name\": \"Optimise for AI search engines ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â AEO and LLMO\",\r\n        \"text\": \"Structure content with clear question-and-answer formatting. Use FAQPage and HowTo schema. Write concise factual answers in the first paragraph.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 7,\r\n        \"name\": \"Track rankings and iterate\",\r\n        \"text\": \"Monitor keyword rankings in Google Search Console and Semrush. Analyse which pages get impressions but low clicks and improve their title tags. Update existing content regularly.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      }\r\n    ]\r\n  },\r\n  {\r\n    \"@context\": \"https://schema.org\",\r\n    \"@type\": \"HowTo\",\r\n    \"name\": \"How to Run Google Ads: Step-by-Step Guide for Beginners\",\r\n    \"description\": \"Learn how to create and run your first Google Ads Search campaign, from account setup to measuring results.\",\r\n    \"totalTime\": \"PT2H\",\r\n    \"estimatedCost\": {\r\n      \"@type\": \"MonetaryAmount\",\r\n      \"currency\": \"INR\",\r\n      \"value\": \"500\"\r\n    },\r\n    \"step\": [\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 1,\r\n        \"name\": \"Create a Google Ads account\",\r\n        \"text\": \"Go to ads.google.com and sign in with your Google account. Select your billing country and time zone. Set up a billing method ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â credit card, debit card, or UPI for India.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 2,\r\n        \"name\": \"Choose your campaign objective\",\r\n        \"text\": \"Select your goal: Sales, Leads, Website traffic, or Brand awareness. For most new advertisers, Leads or Website traffic is the right starting point. Choose Search as the campaign type.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 3,\r\n        \"name\": \"Set your budget and bidding strategy\",\r\n        \"text\": \"Set a daily budget ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â start with ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¹300-500 per day for testing. Choose Maximise clicks as a beginner, or Target CPA once you have enough conversion data.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 4,\r\n        \"name\": \"Research and add keywords\",\r\n        \"text\": \"Use Google Keyword Planner to find keywords your audience searches for. Add a mix of exact, phrase, and broad match keywords. Add negative keywords to exclude irrelevant searches.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 5,\r\n        \"name\": \"Write your ads\",\r\n        \"text\": \"Create Responsive Search Ads with up to 15 headlines and 4 descriptions. Include your primary keyword in several headlines. Add a clear call to action in descriptions.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 6,\r\n        \"name\": \"Set up conversion tracking\",\r\n        \"text\": \"Install Google Tag Manager on your website. Create a conversion action in Google Ads for form submissions or calls. Without conversion tracking you cannot see which keywords generate leads.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 7,\r\n        \"name\": \"Monitor and optimise weekly\",\r\n        \"text\": \"Check the Search Terms report to find irrelevant queries and add them as negatives. Pause keywords with high spend and zero conversions. Review campaigns at least weekly.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-digital-marketing-course\"\r\n      }\r\n    ]\r\n  },\r\n  {\r\n    \"@context\": \"https://schema.org\",\r\n    \"@type\": \"HowTo\",\r\n    \"name\": \"How to Become an Ethical Hacker in India\",\r\n    \"description\": \"A step-by-step roadmap to starting a career in ethical hacking and cyber security in India, from foundational skills to certifications.\",\r\n    \"totalTime\": \"P12M\",\r\n    \"step\": [\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 1,\r\n        \"name\": \"Build networking and OS fundamentals\",\r\n        \"text\": \"Learn how TCP/IP, DNS, HTTP, and firewalls work. Get comfortable with Linux, widely used in security work. Study subnetting, routing, VLANs, and packet analysis with Wireshark.\",\r\n        \"url\": \"https://dizitaladda.com/courses/foundation-in-cyber-security-and-ethical-hacking\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 2,\r\n        \"name\": \"Learn Python for security scripting\",\r\n        \"text\": \"Python is widely used for automation and security tooling. Focus on file handling, socket programming, web scraping, and working with APIs. Libraries like Scapy and Requests are common.\",\r\n        \"url\": \"https://dizitaladda.com/courses/advanced-certification-in-cyber-security-and-ethical-hacking\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 3,\r\n        \"name\": \"Study common attack types and vulnerabilities\",\r\n        \"text\": \"Study the OWASP Top 10 web vulnerabilities: injection, cross-site scripting, broken authentication, IDOR, and SSRF. Understand social engineering, phishing, and password attacks.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-training-in-cyber-security-and-ethical-hacking\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 4,\r\n        \"name\": \"Practice on legal lab environments\",\r\n        \"text\": \"Use platforms like TryHackMe, Hack The Box, and DVWA to practice legally. Set up a local lab using VirtualBox with Kali Linux. Never test real systems without written authorisation.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-training-in-cyber-security-and-ethical-hacking\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 5,\r\n        \"name\": \"Learn penetration testing methodology\",\r\n        \"text\": \"Study the phases of penetration testing: Reconnaissance, Scanning, Gaining Access, Maintaining Access, and Reporting. Learn tools like Nmap, Metasploit, Burp Suite, and Nikto.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-training-in-cyber-security-and-ethical-hacking\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 6,\r\n        \"name\": \"Earn cyber security certifications\",\r\n        \"text\": \"Target certifications recognised in India: CEH, CompTIA Security+, eJPT for beginners, and OSCP for advanced practitioners.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-training-in-cyber-security-and-ethical-hacking\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 7,\r\n        \"name\": \"Participate in bug bounty programmes\",\r\n        \"text\": \"Register on HackerOne, Bugcrowd, and Indian government bug bounty portals. Start with beginner-friendly programmes and build a public portfolio.\",\r\n        \"url\": \"https://dizitaladda.com/courses/expert-traning-in-bug-bounty\"\r\n      }\r\n    ]\r\n  },\r\n  {\r\n    \"@context\": \"https://schema.org\",\r\n    \"@type\": \"HowTo\",\r\n    \"name\": \"How to Learn Data Science from Scratch: A Complete Roadmap for 2026\",\r\n    \"description\": \"A step-by-step roadmap to learning data science in India, from Python basics to machine learning and job placement.\",\r\n    \"totalTime\": \"P12M\",\r\n    \"step\": [\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 1,\r\n        \"name\": \"Learn Python programming\",\r\n        \"text\": \"Python is the primary language of data science. Master variables, loops, functions, and file handling. Then learn NumPy, Pandas, Matplotlib, and Seaborn.\",\r\n        \"url\": \"https://dizitaladda.com/courses/diploma-in-data-science-and-ai\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 2,\r\n        \"name\": \"Study statistics and probability\",\r\n        \"text\": \"Study descriptive statistics, probability distributions, hypothesis testing, correlation, and regression. Statistics is the foundation that makes machine learning results meaningful.\",\r\n        \"url\": \"https://dizitaladda.com/courses/diploma-in-data-science-and-ai\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 3,\r\n        \"name\": \"Learn SQL for data querying\",\r\n        \"text\": \"Learn SELECT, WHERE, GROUP BY, JOIN, and subqueries. Practice on real datasets using MySQL or PostgreSQL. SQL is a core hiring requirement for most data roles.\",\r\n        \"url\": \"https://dizitaladda.com/courses/diploma-in-data-analytics-and-ai\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 4,\r\n        \"name\": \"Master machine learning fundamentals\",\r\n        \"text\": \"Learn core ML algorithms using Scikit-learn: linear regression, logistic regression, decision trees, random forests, and k-means clustering. Evaluate models using train-test split and cross-validation.\",\r\n        \"url\": \"https://dizitaladda.com/courses/diploma-in-machine-learning-and-ai\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 5,\r\n        \"name\": \"Learn deep learning and NLP\",\r\n        \"text\": \"Study neural networks using TensorFlow or PyTorch. Build image classifiers with CNNs and text models using Transformers. Learn tokenisation, sentiment analysis, and named entity recognition.\",\r\n        \"url\": \"https://dizitaladda.com/courses/diploma-in-data-science-and-ai\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 6,\r\n        \"name\": \"Build end-to-end data science projects\",\r\n        \"text\": \"Complete 3-5 projects covering data collection, cleaning, EDA, modelling, evaluation, and deployment. Good ideas include churn prediction, fraud detection, and demand forecasting. Host projects on GitHub.\",\r\n        \"url\": \"https://dizitaladda.com/courses/diploma-in-data-science-and-ai\"\r\n      },\r\n      {\r\n        \"@type\": \"HowToStep\",\r\n        \"position\": 7,\r\n        \"name\": \"Apply for data science roles in India\",\r\n        \"text\": \"Target roles including Junior Data Scientist, ML Engineer, Data Analyst, and AI Engineer. Entry-level salaries vary by company, skills, and city.\",\r\n        \"url\": \"https://dizitaladda.com/courses/diploma-in-data-science-and-ai\"\r\n      }\r\n    ]\r\n  }\r\n]\r\n"}} />

 

 

